1	// The constructor keeps a public named param (`localAuthentication`)
2	// distinct from the private field it initializes, matching
3	// `session_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'dart:async';
6	
7	import 'package:fpdart/fpdart.dart';
8	import 'package:local_auth/local_auth.dart';
9	
10	import '../../../../core/failure/failure.dart';
11	import '../../domain/entities/vault_status.dart';
12	import '../../domain/repositories/vault_repository.dart';
13	
14	/// Owns the one broadcast [VaultStatus] stream the epic's AD-14 seam
15	/// requires. Covers the I/O matrix (spec-2-1):
16	/// - biometrics succeed -> [VaultStatus.unlocked] emitted, `Right(unit)`.
17	/// - biometrics fail/cancelled/unavailable (`authenticate()` returns
18	///   `false`, or throws `LocalAuthException`) -> status stays
19	///   [VaultStatus.locked], `Left(Failure.malformedResponse(...))`.
20	///
21	/// Zero network calls anywhere in this class (Boundaries: "Vault makes zero
22	/// network calls") and never produces [Failure.authInvalid] (Boundaries:
23	/// reserved for password login) — both the `false` and the thrown-exception
24	/// branches below map only to [Failure.malformedResponse].
25	class VaultRepositoryImpl implements VaultRepository {
26	  VaultRepositoryImpl({required LocalAuthentication localAuthentication})
27	    : _localAuthentication = localAuthentication;
28	
29	  final LocalAuthentication _localAuthentication;
30	  final StreamController<VaultStatus> _statusController =
31	      StreamController<VaultStatus>.broadcast();
32	
33	  /// The last status emitted. Starts at [VaultStatus.locked] — not
34	  /// nullable, see [VaultStatus]'s own doc — so [currentStatus] is correct
35	  /// synchronously from construction, with no async warm-up step.
36	  VaultStatus _lastStatus = VaultStatus.locked;
37	
38	  @override
39	  VaultStatus get currentStatus => _lastStatus;
40	
41	  @override
42	  Stream<VaultStatus> get statusStream {
43	    // Same `Stream.multi` replay-to-late-listeners rationale as
44	    // `SessionRepositoryImpl.statusStream`: a listener that subscribes
45	    // after construction (but before any [authenticate] call) still
46	    // immediately sees the cached [_lastStatus] ([VaultStatus.locked])
47	    // rather than nothing until the next emission.
48	    return Stream<VaultStatus>.multi((controller) {
49	      controller.add(_lastStatus);
50	      final subscription = _statusController.stream.listen(
51	        controller.add,
52	        onError: controller.addError,
53	        onDone: controller.close,
54	      );
55	      controller.onCancel = subscription.cancel;
56	    }, isBroadcast: true);
57	  }
58	
59	  void _emit(VaultStatus status) {
60	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
61	    // an in-flight `authenticate()` call — mirrors
62	    // `SessionRepositoryImpl._emit`'s own guard.
63	    if (_statusController.isClosed) {
64	      return;
65	    }
66	    _lastStatus = status;
67	    _statusController.add(status);
68	  }
69	
70	  @override
71	  Future<Either<Failure, Unit>> authenticate() async {
72	    try {
73	      // `biometricOnly: true` (Boundaries/Design Notes) — never lets the
74	      // OS's own device-passcode UI satisfy this call, which would bypass
75	      // Cerne's own PIN screen (Story 2.2) entirely.
76	      // `persistAcrossBackgrounding: true` so a backgrounding mid-prompt
77	      // (e.g. an incoming call) retries on foreground instead of failing
78	      // outright.
79	      final success = await _localAuthentication.authenticate(
80	        localizedReason: 'Autentique-se para acessar o Cerne',
81	        biometricOnly: true,
82	        persistAcrossBackgrounding: true,
83	      );
84	      if (success) {
85	        _emit(VaultStatus.unlocked);
86	        return right(unit);
87	      }
88	      // A `false` result (declined/unavailable, no exception) — status
89	      // stays `locked`; never `Failure.authInvalid` (Boundaries: reserved
90	      // for password login).
91	      return left(
92	        const Failure.malformedResponse(
93	          message: 'Biometric authentication was not successful',
94	        ),
95	      );
96	    } on LocalAuthException catch (error) {
97	      // Covers cancellation, no enrolled biometrics, hardware unavailable,
98	      // etc. (RNF09: never let a platform exception escape unmapped).
99	      return left(Failure.malformedResponse(message: error.toString()));
100	    } catch (error) {
101	      // Any other thrown platform exception (e.g. the plugin's channel
102	      // itself failing) must never escape unmapped either (RNF09) — fail
103	      // closed, same as the documented `LocalAuthException` branch above,
104	      // mirroring `SessionRepositoryImpl.restoreSession()`'s own plain
105	      // `catch`.
106	      return left(Failure.malformedResponse(message: error.toString()));
107	    }
108	  }
109	
110	  @override
111	  Future<void> dispose() async {
112	    await _statusController.close();
113	  }
114	}
