7	/// Registers the `vault` feature into the project's single `get_it`
8	/// instance (`sl`) — mirrors `features/auth/auth_injection.dart`'s pattern.
9	/// Called from `setupCoreDependencies()` right after `registerAuthFeature()`
10	/// (Code Map).
11	void registerVaultFeature() {
12	  sl.registerLazySingleton<LocalAuthentication>(() => LocalAuthentication());
13	
14	  // The epic's ONE new DI-singleton access point for device-level access
15	  // (AD-14) — registered as a singleton so every consumer (the `/vault`
16	  // lock screen; `core/navigation/app_router.dart`'s redirect; `main.dart`)
17	  // shares the same `statusStream`, not a fresh instance each. `dispose:`
18	  // wires `VaultRepository.dispose()` into `get_it`'s own reset lifecycle,
19	  // so `resetCoreDependencies()` (`sl.reset()`) closes its
20	  // `StreamController` instead of leaking one on every test teardown.
21	  sl.registerLazySingleton<VaultRepository>(
22	    () => VaultRepositoryImpl(localAuthentication: sl<LocalAuthentication>()),
23	    dispose: (repository) => repository.dispose(),
24	  );
25	}
