8	/// `/vault` — the epic's one lock screen, shown whenever
9	/// `VaultRepository.currentStatus` isn't `VaultStatus.unlocked`
10	/// (`core/navigation/app_router.dart`'s `_redirect`). Auto-triggers the OS
11	/// biometric prompt once in [initState]; a successful
12	/// [VaultRepository.authenticate] call flips `currentStatus` to `unlocked`,
13	/// which — via `statusStream`/`refreshListenable` — re-runs the redirect and
14	/// navigates away from here on its own, so this widget never navigates
15	/// imperatively itself. No PIN entry UI (Story 2.2).
16	class VaultLockScreen extends StatefulWidget {
17	  const VaultLockScreen({required this.vaultRepository, super.key});
18	
19	  final VaultRepository vaultRepository;
20	
21	  @override
22	  State<VaultLockScreen> createState() => _VaultLockScreenState();
23	}
24	
25	class _VaultLockScreenState extends State<VaultLockScreen> {
26	  bool _authenticating = false;
27	  bool _showRetry = false;
28	
29	  @override
30	  void initState() {
31	    super.initState();
32	    _attemptAuthenticate();
33	  }
34	
35	  Future<void> _attemptAuthenticate() async {
36	    if (_authenticating) {
37	      return;
38	    }
39	    setState(() {
40	      _authenticating = true;
41	      _showRetry = false;
42	    });
43	
44	    final result = await widget.vaultRepository.authenticate();
45	    if (!mounted) {
46	      return;
47	    }
48	
49	    // On success, `currentStatus` is already `unlocked` and the router's
50	    // own `refreshListenable` will navigate away from `/vault` on its own —
51	    // this widget has nothing further to do (and may already be in the
52	    // process of being disposed by the time that happens).
53	    result.match(
54	      (_) => setState(() {
55	        _authenticating = false;
56	        _showRetry = true;
57	      }),
58	      (_) => setState(() {
59	        _authenticating = false;
60	      }),
61	    );
62	
63	    // `Semantics(liveRegion: true)` below is primarily honored by Android's
64	    // TalkBack; this app is iOS-only, where VoiceOver doesn't reliably treat
65	    // a live-region subtree update as an announcement. `sendAnnouncement()`
66	    // is honored on both platforms, so the failure transition is still
67	    // spoken even if the live-region flag alone isn't.
68	    if (_showRetry && mounted) {
69	      await SemanticsService.sendAnnouncement(
70	        View.of(context),
71	        'Não foi possível reconhecer. Toque em Tentar novamente.',
72	        TextDirection.ltr,
73	      );
74	    }
75	  }
76	
77	  @override
78	  Widget build(BuildContext context) {
79	    return Scaffold(
80	      backgroundColor: DesignTokens.colorSurfaceBg,
81	      body: Center(
82	        child: Padding(
83	          padding: DesignTokens.screenPadding,
84	          // `liveRegion: true` so a screen reader announces the subtree's
85	          // content whenever it changes — in particular the "autenticando"
86	          // -> retry-button transition below (_showRetry flipping true),
87	          // instead of staying silent about that state change.
88	          child: Semantics(
89	            liveRegion: true,
90	            child: Column(
91	              mainAxisSize: MainAxisSize.min,
92	              children: [
93	                const Icon(
94	                  Icons.lock_outline,
95	                  size: DesignTokens.spacing2xl,
96	                  color: DesignTokens.colorTextSecondary,
97	                ),
98	                const SizedBox(height: DesignTokens.spacingMd),
99	                Text(
100	                  'Cerne bloqueado',
101	                  textAlign: TextAlign.center,
102	                  style: DesignTokens.textHeadlineMd.copyWith(
103	                    color: DesignTokens.colorTextPrimary,
104	                  ),
105	                ),
106	                const SizedBox(height: DesignTokens.spacingSm),
107	                Text(
108	                  'Use a biometria do seu dispositivo para continuar.',
109	                  textAlign: TextAlign.center,
110	                  style: DesignTokens.textBodyMd.copyWith(
111	                    color: DesignTokens.colorTextSecondary,
112	                  ),
113	                ),
114	                if (_showRetry) ...[
115	                  const SizedBox(height: DesignTokens.spacingLg),
116	                  AppButton(
117	                    label: 'Tentar novamente',
118	                    onPressed: _attemptAuthenticate,
119	                  ),
120	                ],
121	              ],
122	            ),
123	          ),
124	        ),
125	      ),
126	    );
127	  }
128	}
