12	/// Same shape as `app_router_test.dart`'s own `_FakeVaultRepository` — a
13	/// plain fake (not mocktail) so `authenticate()`'s resolution can be held
14	/// open with a `Completer`, which this suite needs to observe the screen's
15	/// mid-flight state (no retry button while `_authenticating` is true).
16	class _FakeVaultRepository implements VaultRepository {
17	  VaultStatus _status = VaultStatus.locked;
18	  final _controller = StreamController<VaultStatus>.broadcast();
19	
20	  /// Controls what the NEXT `authenticate()` call resolves to. Defaults to
21	  /// `false` (a quiet decline), matching `app_router_test.dart`'s own
22	  /// default so a bare `pumpWidget` never silently unlocks.
23	  bool authenticateSucceeds = false;
24	
25	  /// Lets a test hold `authenticate()` unresolved to inspect the
26	  /// `_authenticating`-true frame before letting it settle.
27	  Completer<void>? authenticateGate;
28	
29	  int authenticateCallCount = 0;
30	
31	  @override
32	  VaultStatus get currentStatus => _status;
33	
34	  @override
35	  Stream<VaultStatus> get statusStream => _controller.stream;
36	
37	  @override
38	  Future<Either<Failure, Unit>> authenticate() async {
39	    authenticateCallCount += 1;
40	    final gate = authenticateGate;
41	    if (gate != null) {
42	      await gate.future;
43	    }
44	    if (authenticateSucceeds) {
45	      _status = VaultStatus.unlocked;
46	      _controller.add(_status);
47	      return right(unit);
48	    }
49	    return left(
50	      const Failure.malformedResponse(message: 'fake: biometrics declined'),
51	    );
52	  }
53	
54	  @override
55	  Future<void> dispose() => _controller.close();
56	}
57	
58	Widget _wrap(VaultRepository vaultRepository) {
59	  return MaterialApp(
60	    home: VaultLockScreen(vaultRepository: vaultRepository),
61	  );
62	}
63	
64	/// End-to-end widget coverage for the epic's one lock screen
65	/// (spec-2-1) — `app_router_test.dart` already proves the *routing*
66	/// consequences of `VaultStatus` (AD-14); this suite proves the screen's
67	/// own user-visible flow in isolation: auto-prompt on mount, the
68	/// decline -> "Tentar novamente" transition, and retry re-triggering
69	/// `authenticate()`.
70	void main() {
71	  late _FakeVaultRepository fakeVaultRepository;
72	
73	  setUp(() {
74	    fakeVaultRepository = _FakeVaultRepository();
75	  });
76	
77	  tearDown(() => fakeVaultRepository.dispose());
78	
79	  testWidgets(
80	    'mounts -> auto-triggers authenticate() exactly once, with no user '
81	    'interaction',
82	    (tester) async {
83	      await tester.pumpWidget(_wrap(fakeVaultRepository));
84	      await tester.pumpAndSettle();
85	
86	      expect(fakeVaultRepository.authenticateCallCount, 1);
87	    },
88	  );
89	
90	  testWidgets(
91	    'while authenticate() is still pending, the lock copy is shown and no '
92	    'retry button is offered',
93	    (tester) async {
94	      fakeVaultRepository.authenticateGate = Completer<void>();
95	
96	      await tester.pumpWidget(_wrap(fakeVaultRepository));
97	      await tester.pump();
98	
99	      expect(find.text('Cerne bloqueado'), findsOneWidget);
100	      expect(find.text('Tentar novamente'), findsNothing);
101	
102	      fakeVaultRepository.authenticateGate!.complete();
103	      await tester.pumpAndSettle();
104	    },
105	  );
106	
107	  testWidgets(
108	    'authenticate() succeeds on mount -> no retry button, no exception, '
109	    'status flips to unlocked',
110	    (tester) async {
111	      fakeVaultRepository.authenticateSucceeds = true;
112	
113	      await tester.pumpWidget(_wrap(fakeVaultRepository));
114	      await tester.pumpAndSettle();
115	
116	      expect(tester.takeException(), isNull);
117	      expect(find.text('Tentar novamente'), findsNothing);
118	      expect(fakeVaultRepository.currentStatus, VaultStatus.unlocked);
119	    },
120	  );
121	
122	  testWidgets(
123	    'authenticate() declines on mount -> "Tentar novamente" button shown, '
124	    'vault stays locked',
125	    (tester) async {
126	      await tester.pumpWidget(_wrap(fakeVaultRepository));
127	      await tester.pumpAndSettle();
128	
129	      expect(find.text('Tentar novamente'), findsOneWidget);
130	      expect(fakeVaultRepository.currentStatus, VaultStatus.locked);
131	    },
132	  );
133	
134	  testWidgets(
135	    'tapping "Tentar novamente" re-invokes authenticate(); a second success '
