24	/// A plain (non-mocktail) fake — the overlay/router tests below need
25	/// [currentStatus] to reflect whatever [setStatus] last set, read
26	/// synchronously by the router's `redirect`, while also actually emitting
27	/// on [statusStream] so both the router's `refreshListenable` and
28	/// `ExpiryOverlayHost`'s own subscription react — the same reason
29	/// `app_router_test.dart` uses one instead of a mocktail stub.
30	class _FakeSessionRepository implements SessionRepository {
31	  _FakeSessionRepository({Either<Failure, Unit>? restoreSessionResult})
32	    : _restoreSessionResult = restoreSessionResult ?? right(unit);
33	
34	  final Either<Failure, Unit> _restoreSessionResult;
35	  SessionStatus? _status;
36	  final _controller = StreamController<SessionStatus>.broadcast();
37	
38	  @override
39	  SessionStatus? get currentStatus => _status;
40	
41	  @override
42	  Stream<SessionStatus> get statusStream => _controller.stream;
43	
44	  @override
45	  Future<Either<Failure, Unit>> restoreSession() async => _restoreSessionResult;
46	
47	  @override
48	  void markAuthenticated() => setStatus(SessionStatus.authenticated);
49	
50	  @override
51	  Future<void> dispose() => _controller.close();
52	
53	  void setStatus(SessionStatus status) {
54	    _status = status;
